package io.peekandpoke.ultra.datetime

import io.peekandpoke.ultra.common.ComparableTo
import io.peekandpoke.ultra.common.slumber.Slumber
import kotlinx.datetime.DateTimeUnit
import kotlinx.datetime.DayOfWeek
import kotlinx.datetime.TimeZone
import kotlinx.serialization.Serializable
import kotlin.math.abs
import kotlin.time.Duration

/**
 * An instant seen in a [timezone].
 *
 * The instant is the truth (ULTRA-00211): [datetime] and every local field are derived from it, so both sides of a
 * DST overlap are distinct values. Build one with [MpInstant.atZone], or from a local time with [of].
 */
@Suppress("Detekt:TooManyFunctions")
@Serializable(with = MpZonedDateTimeSerializer::class)
@Slumber.As(MpDateTimeRawData::class)
class MpZonedDateTime private constructor(
    private val instant: MpInstant,
    val timezone: MpTimezone,
) : MpAbsoluteDateTime, ComparableTo<MpZonedDateTime> {

    companion object {
        /**
         * Creates from a local [datetime] and a [timezone]
         */
        fun of(datetime: MpLocalDateTime, timezone: TimeZone): MpZonedDateTime {
            return of(datetime = datetime, timezone = timezone.mp)
        }

        /**
         * Creates from a local [datetime] and a [timezone].
         *
         * In a DST overlap the earlier offset wins; in a gap the time moves forward by the length of the gap, and
         * [MpZonedDateTime.datetime] reads the resolved wall time.
         */
        fun of(datetime: MpLocalDateTime, timezone: MpTimezone): MpZonedDateTime {
            return MpZonedDateTime(instant = datetime.toInstant(timezone), timezone = timezone)
        }

        /** The [instant] in the [timezone], unchanged. */
        internal fun of(instant: MpInstant, timezone: MpTimezone): MpZonedDateTime {
            return MpZonedDateTime(instant = instant, timezone = timezone)
        }

        /**
         * Creates from the given epoch [millis] and [timezone].
         */
        fun fromEpochMillis(millis: Long, timezone: TimeZone): MpZonedDateTime {
            return fromEpochMillis(millis = millis, timezone = timezone.mp)
        }

        /**
         * Creates from the given epoch [millis] and [timezone].
         */
        fun fromEpochMillis(millis: Long, timezone: MpTimezone): MpZonedDateTime {
            return MpInstant.fromEpochMillis(millis).atZone(timezone)
        }

        /**
         * Creates from the given epoch [seconds] and [timezone].
         */
        fun fromEpochSeconds(seconds: Long, timezone: TimeZone): MpZonedDateTime {
            return fromEpochSeconds(seconds = seconds, timezone = timezone.mp)
        }

        /**
         * Creates from the given epoch [seconds] and [timezone].
         */
        fun fromEpochSeconds(seconds: Long, timezone: MpTimezone): MpZonedDateTime {
            return MpInstant.fromEpochSeconds(seconds).atZone(timezone)
        }

        /**
         * Parses from an [isoString] and a [timezone].
         *
         * Throws an [IllegalArgumentException] if parsing fails.
         */
        @Throws(IllegalArgumentException::class)
        fun parse(isoString: String, timezone: TimeZone): MpZonedDateTime {
            return parse(isoString, timezone.mp)
        }

        /**
         * Parses from an [isoString] and a [timezone].
         *
         * Throws an [IllegalArgumentException] if parsing fails.
         */
        @Throws(IllegalArgumentException::class)
        fun parse(isoString: String, timezone: MpTimezone): MpZonedDateTime {
            return parse(isoString).atZone(timezone)
        }

        /**
         * Parses from an [isoString] and a [timezone].
         *
         * Returns null if parsing fails.
         */
        fun tryParse(isoString: String, timezone: TimeZone): MpZonedDateTime? {
            return tryParse(isoString, timezone.mp)
        }

        /**
         * Parses from an [isoString] and a [timezone].
         *
         * Returns null if parsing fails.
         */
        fun tryParse(isoString: String, timezone: MpTimezone): MpZonedDateTime? {
            return try {
                parseInternal(isoString).atZone(timezone)
            } catch (_: Throwable) {
                null
            }
        }

        /**
         * Parses from an [isoString] and tries to obtain the timezone from it.
         *
         * If there is no timezone in the [isoString] it will fall back to UTC.
         *
         * Throws an [IllegalArgumentException] if parsing fails.
         */
        @Throws(IllegalArgumentException::class)
        fun parse(isoString: String): MpZonedDateTime {
            return try {
                parseInternal(isoString)
            } catch (e: Throwable) {
                throw IllegalArgumentException("Could not parse MpZonedDateTime from '$isoString'", e)
            }
        }

        /**
         * Parses from an [isoString] and tries to obtain the timezone from it.
         *
         * If there is no timezone in the [isoString] it will fall back to UTC.
         *
         * Returns null if parsing fails.
         */
        fun tryParse(isoString: String): MpZonedDateTime? {
            return try {
                parseInternal(isoString)
            } catch (_: Throwable) {
                null
            }
        }

        private fun parseInternal(isoString: String): MpZonedDateTime {
            return MpDateTimeParser.parseZonedDateTime(isoString)
        }

        /**
         * The Genesis, a date in the distant past: -10000-01-01T00:00:00Z
         */
        val Genesis: MpZonedDateTime = MpInstant.Genesis.atZone(MpTimezone.UTC)

        /**
         * The Doomsday, a date in the distant future: +10000-01-01T00:00:00Z
         */
        val Doomsday: MpZonedDateTime = MpInstant.Doomsday.atZone(MpTimezone.UTC)
    }

    /** The wall-clock time of the instant in the [timezone]. */
    val datetime: MpLocalDateTime = MpLocalDateTime(TimezoneEngine.toLocalDateTime(timezone, instant.value))

    /**
     * Equal when the instant and the [timezone] are equal (ULTRA-00211): the two sides of a DST overlap differ, a time
     * in a gap equals the time it resolves to. The one place that decides equality, together with [hashCode].
     */
    override fun equals(other: Any?): Boolean {
        return other is MpZonedDateTime && instant == other.instant && timezone == other.timezone
    }

    override fun hashCode(): Int {
        return 31 * instant.hashCode() + timezone.hashCode()
    }

    /** The year */
    val year: Int get() = datetime.year

    /** The month as number, where January is "1" */
    val monthNumber: Int get() = datetime.monthNumber

    /** The month */
    val month: MpMonth get() = datetime.month

    /** The day of the month */
    val dayOfMonth: Int get() = datetime.dayOfMonth

    /** The hour */
    val hour: Int get() = datetime.hour

    /** The minute */
    val minute: Int get() = datetime.minute

    /** The second */
    val second: Int get() = datetime.second

    /** The millisecond */
    val milliSecond: Int get() = datetime.milliSecond

    /** The day of the week */
    val dayOfWeek: MpDayOfWeek get() = datetime.dayOfWeek

    /** The day of the year */
    val dayOfYear: Int get() = datetime.dayOfYear

    /**
     * Orders by instant, then by local date-time, then by zone id, like java.time's `ChronoZonedDateTime`, so `0`
     * exactly when [equals]. To compare by point in time only, use [isSameInstant].
     */
    override fun compareTo(other: MpZonedDateTime): Int {
        val byInstant = instant.compareTo(other.instant)
        if (byInstant != 0) return byInstant

        val byLocal = datetime.compareTo(other.datetime)
        if (byLocal != 0) return byLocal

        return timezone.id.compareTo(other.timezone.id)
    }

    /**
     * Converts to string.
     */
    override fun toString(): String {
        val iso = toIsoString()
        val zoneStart = iso.lastIndexOf('[')

        // The offset tells the two sides of a DST overlap apart; toIsoString() stays without it (ULTRA-00211).
        return when {
            zoneStart < 0 -> "MpZonedDateTime($iso)"
            else -> "MpZonedDateTime(${iso.substring(0, zoneStart)}${offsetText()}${iso.substring(zoneStart)})"
        }
    }

    /** The offset at the instant as `+hh:mm`, or `+hh:mm:ss` when it has seconds. */
    private fun offsetText(): String {
        val total = timezone.offsetSecondsAt(instant)
        val sign = if (total < 0) "-" else "+"
        val absolute = abs(total)

        fun Int.pad() = toString().padStart(2, '0')

        val hoursMinutes = "$sign${(absolute / 3600).pad()}:${(absolute % 3600 / 60).pad()}"

        return if (absolute % 60 == 0) hoursMinutes else "$hoursMinutes:${(absolute % 60).pad()}"
    }

    /**
     * Converts into a human-readable string by the given [formatString].
     *
     * See https://help.gooddata.com/cloudconnect/manual/date-and-time-format.html
     */
    fun format(formatString: String): String {
        val offsetMillis = timezone.offsetMillisAt(instant)

        val offsetString = when {
            offsetMillis == 0L -> "Z"
            else -> {
                val sign = if (offsetMillis >= 0) "+" else "-"
                val absMillis = abs(offsetMillis)
                val h = (absMillis / 3_600_000).toInt()
                val m = ((absMillis % 3_600_000) / 60_000).toInt()
                "$sign${h.toString().padStart(2, '0')}${m.toString().padStart(2, '0')}"
            }
        }

        return MpDateTimeFormatter.format(
            pattern = formatString,
            year = year,
            month = monthNumber,
            day = dayOfMonth,
            hour = hour,
            minute = minute,
            second = second,
            millis = milliSecond,
            offsetString = offsetString,
        )
    }

    /**
     * Converts to an iso date string.
     */
    fun toIsoString(): String {

        fun Number.pad(n: Int = 2) = toString().padStart(n, '0')

        val tz = when (val tzId = timezone.id) {
            "UTC", "Z" -> "Z"
            else -> "[$tzId]"
        }

        val yearStr = when {
            year > 9999 -> "+$year"
            else -> year.pad(4)
        }

        return "$yearStr-${monthNumber.pad()}-${dayOfMonth.pad()}T" +
                "${hour.pad()}:${minute.pad()}:${second.pad()}." +
                milliSecond.pad(3) +
                tz
    }

    /**
     * Converts to an [MpInstant].
     */
    override fun toInstant(): MpInstant = instant

    /**
     * Converts to an [MpLocalDate].
     */
    fun toLocalDate(): MpLocalDate = datetime.toDate()

    /**
     * Converts to an [MpLocalTime].
     */
    fun toLocalTime(): MpLocalTime = datetime.toTime()

    /**
     * Converts to an [MpLocalDateTime].
     */
    fun toLocalDateTime(): MpLocalDateTime = datetime

    /**
     * Gets the epoch millis.
     */
    fun toEpochMillis(): Long = toInstant().toEpochMillis()

    /**
     * Gets the epoch seconds.
     */
    fun toEpochSeconds(): Long = toInstant().toEpochSeconds()

    /**
     * Creates a [MpZonedDateTimeRange] with this as the start and the given [duration].
     */
    fun toRange(duration: Duration): MpZonedDateTimeRange {
        return MpZonedDateTimeRange.of(from = this, duration = duration)
    }

    /**
     * Creates a [MpZonedDateTimeRange] with this as the start and the given [period].
     */
    fun toRange(period: MpTemporalPeriod): MpZonedDateTimeRange {
        return MpZonedDateTimeRange.of(from = this, period = period)
    }

    /**
     * Get the start of the year: the start of its first day, see [atStartOfDay].
     */
    fun atStartOfYear(): MpZonedDateTime = MpLocalDate.of(year, 1, 1).atStartOfDay(timezone)

    /**
     * Get the start of the month: the start of its first day, see [atStartOfDay].
     */
    fun atStartOfMonth(): MpZonedDateTime = MpLocalDate.of(year, monthNumber, 1).atStartOfDay(timezone)

    /**
     * Get the start of the day: midnight, or the end of the gap when midnight does not exist (java.time's rule).
     */
    fun atStartOfDay(): MpZonedDateTime = toLocalDate().atStartOfDay(timezone)

    /**
     * Get the start of the hour, keeping the current offset in a DST overlap.
     *
     * A start that falls into a DST gap resolves like [of], so the result can be later than this one (Toronto
     * 1919-03-31T00:45 gives 01:00).
     */
    fun atStartOfHour(): MpZonedDateTime = withLocal(MpLocalDateTime.of(year, monthNumber, dayOfMonth, hour))

    /**
     * Get the start of the minute, keeping the current offset in a DST overlap.
     */
    fun atStartOfMinute(): MpZonedDateTime =
        withLocal(MpLocalDateTime.of(year, monthNumber, dayOfMonth, hour, minute))

    /**
     * Get the start of the second, keeping the current offset in a DST overlap.
     */
    fun atStartOfSecond(): MpZonedDateTime =
        withLocal(MpLocalDateTime.of(year, monthNumber, dayOfMonth, hour, minute, second))

    /** The local [datetime] in this zone, keeping the current offset where it is still valid (java.time's rule). */
    private fun withLocal(datetime: MpLocalDateTime): MpZonedDateTime {
        val resolved = TimezoneEngine.toInstant(
            timezone = timezone,
            local = datetime.value,
            preferredOffsetSeconds = timezone.offsetSecondsAt(instant),
        )

        return MpZonedDateTime(instant = MpInstant(resolved), timezone = timezone)
    }

    /**
     * Gets the start of the upcoming [dayOfWeek].
     */
    fun atStartOfNext(dayOfWeek: DayOfWeek): MpZonedDateTime = atStartOfNext(dayOfWeek.mp)

    /**
     * Gets the start of the upcoming [dayOfWeek], after today.
     *
     * When the zone skips that date (Samoa skipped 2011-12-30), the start of the day after it, like [atStartOfDay].
     */
    fun atStartOfNext(dayOfWeek: MpDayOfWeek): MpZonedDateTime {
        // Steps on the date: stepping on the zoned value looped forever over a day the zone skips (ULTRA-00211)
        return toLocalDate().atStartOfNext(dayOfWeek).atStartOfDay(timezone)
    }

    /**
     * Gets the start of the preceding [dayOfWeek].
     */
    fun atStartOfPrevious(dayOfWeek: DayOfWeek): MpZonedDateTime = atStartOfPrevious(dayOfWeek.mp)

    /**
     * Gets the start of the preceding [dayOfWeek], today included.
     *
     * When the zone skips that date (Samoa skipped 2011-12-30), the start of the day after it, like [atStartOfDay].
     */
    fun atStartOfPrevious(dayOfWeek: MpDayOfWeek): MpZonedDateTime {
        // Steps on the date: stepping on the zoned value looped forever over a day the zone skips (ULTRA-00211)
        return toLocalDate().atStartOfPrevious(dayOfWeek).atStartOfDay(timezone)
    }

    /**
     * Sets the time of the day to the given [time], keeping the current offset in a DST overlap.
     *
     * [MpLocalTime.EndOfDay] (24:00) gives the start of the next day, see [atStartOfDay].
     */
    fun atTime(time: MpLocalTime): MpZonedDateTime {
        if (time.isEndOfDay) return toLocalDate().plusDays(1).atStartOfDay(timezone)

        return withLocal(MpLocalDateTime.of(date = toLocalDate(), time = time))
    }

    /**
     * Add the given [duration] in absolute terms.
     */
    fun plus(duration: Duration): MpZonedDateTime {
        return toInstant().plus(duration).atZone(timezone)
    }

    /**
     * Adds once the [unit] by taking the [timezone] into account.
     *
     * This method is useful for timezones where there is a DST (Daylight Saving Transition).
     *
     * For example adding 1 Day to 2022-03-27T00:00:00[Europe/Berlin]
     * Will result in              2022-03-28T00:00:00[Europe/Berlin]
     * while the difference between both instants is only 23 hours.
     */
    fun plus(unit: DateTimeUnit): MpZonedDateTime {
        return plus(1, unit)
    }

    /**
     * Adds the [value] times [unit] by taking the [timezone] into account.
     *
     * This method is useful for timezones where there is a DST (Daylight Saving Transition).
     *
     * For example adding 1 Day to 2022-03-27T00:00:00[Europe/Berlin]
     * Will result in              2022-03-28T00:00:00[Europe/Berlin]
     * while the difference between both instants is only 23 hours.
     */
    fun plus(value: Int, unit: DateTimeUnit): MpZonedDateTime {
        return toInstant().plus(value, unit, timezone).atZone(timezone)
    }

    /**
     * Adds the given [period] in the [timezone].
     *
     * Each component is added individually starting with years, months, ..., milliseconds
     */
    fun plus(period: MpTemporalPeriod): MpZonedDateTime {
        return toInstant().plus(period, timezone).atZone(timezone)
    }

    /**
     * Subtracts the given duration in absolute terms.
     */
    fun minus(duration: Duration): MpZonedDateTime {
        return toInstant().minus(duration).atZone(timezone)
    }

    /**
     * Subtracts once the [unit] by taking the [timezone] into account.
     *
     * This method is useful for timezones where there is a DST (Daylight Saving Transition).
     *
     * For example subtracting 1 Day to 2022-03-28T00:00:00[Europe/Berlin]
     * Will result in                   2022-03-27T00:00:00[Europe/Berlin]
     * while the difference between both instants is only 23 hours.
     */
    fun minus(unit: DateTimeUnit): MpZonedDateTime {
        return minus(1, unit)
    }

    /**
     * Subtracts the [value] times [unit] by taking the [timezone] into account.
     *
     * This method is useful for timezones where there is a DST (Daylight Saving Transition).
     *
     * For example subtracting 1 Day to 2022-03-28T00:00:00[Europe/Berlin]
     * Will result in                   2022-03-27T00:00:00[Europe/Berlin]
     * while the difference between both instants is only 23 hours.
     */
    fun minus(value: Int, unit: DateTimeUnit): MpZonedDateTime {
        return plus(-value, unit)
    }

    /**
     * Calculates the [Duration] between this and the [other] date time.
     */
    operator fun minus(other: MpZonedDateTime): Duration {
        return toInstant() - other.toInstant()
    }

    /**
     * Subtracts the given [period] in the [timezone].
     *
     * Each component is added individually starting with years, months, ..., milliseconds
     */
    fun minus(period: MpTemporalPeriod): MpZonedDateTime {
        return plus(-period)
    }
}

fun MpZonedDateTime.formatDdMmmYyyy(): String {
    return format("dd MMM yyyy")
}

fun MpZonedDateTime.formatHhMm(): String {
    return format("HH:mm")
}

fun MpZonedDateTime.formatDdMmmYyyyHhMm(): String {
    return format("dd MMM yyyy HH:mm")
}

fun MpZonedDateTime.formatDdMmmYyyyHhMmSs(): String {
    return format("dd MMM yyyy HH:mm:ss")
}
